package com.martin_thoma.drift.core.ringing

import androidx.annotation.RawRes
import androidx.annotation.StringRes

enum class SoundCategory { NATURE, NOISY, CLASSICS }

/** A sound that ships with the app (generated by scripts/make_alarm_sounds.py). An alarm stores its [uri]. */
data class BuiltInSound(
    val id: String,
    val category: SoundCategory?,
    @param:StringRes val title: Int,
    @param:RawRes internal val raw: Int,
) {
    val uri: String get() = AlarmSounds.BUILT_IN_PREFIX + id
}

/** A sound file the user added. The app keeps its own copy, named [fileName]. */
data class CustomSound(
    val fileName: String,
) {
    val uri: String get() = AlarmSounds.CUSTOM_PREFIX + fileName
    val title: String get() = fileName.substringBeforeLast('.')
}

/** The sounds an alarm can ring with. An alarm without a sound (`soundUri == null`) rings with [Default]. */
object AlarmSounds {
    internal const val BUILT_IN_PREFIX = "drift:sound/"
    internal const val CUSTOM_PREFIX = "drift:custom/"

    val Default = BuiltInSound("chime", null, R.string.core_ringing_sound_default, R.raw.chime)

    val builtIn: List<BuiltInSound> =
        listOf(
            Default,
            BuiltInSound("sea", SoundCategory.NATURE, R.string.core_ringing_sound_sea, R.raw.sound_sea),
            BuiltInSound("rain", SoundCategory.NATURE, R.string.core_ringing_sound_rain, R.raw.sound_rain),
            BuiltInSound("thunder", SoundCategory.NATURE, R.string.core_ringing_sound_thunder, R.raw.sound_thunder),
            BuiltInSound("crickets", SoundCategory.NATURE, R.string.core_ringing_sound_crickets, R.raw.sound_crickets),
            BuiltInSound("alarm_clock", SoundCategory.NOISY, R.string.core_ringing_sound_alarm_clock, R.raw.sound_alarm_clock),
            BuiltInSound("canon_in_d", SoundCategory.CLASSICS, R.string.core_ringing_sound_canon_in_d, R.raw.sound_canon_in_d),
            BuiltInSound("fur_elise", SoundCategory.CLASSICS, R.string.core_ringing_sound_fur_elise, R.raw.sound_fur_elise),
        )

    /**
     * No sound at all: the alarm wakes by vibration and light only. Chosen on purpose, so unlike a
     * sound that fails, it never falls back to the chime.
     */
    const val SILENT_URI = "drift:sound/none"

    fun isSilent(soundUri: String?): Boolean = soundUri == SILENT_URI

    /** The built-in sound an alarm with [soundUri] rings with, or `null` for any other sound. */
    fun builtIn(soundUri: String?): BuiltInSound? = if (soundUri == null) Default else builtIn.find { it.uri == soundUri }

    /** The user's sound an alarm with [soundUri] rings with, or `null` for any other sound. */
    fun custom(soundUri: String?): CustomSound? =
        soundUri?.takeIf { it.startsWith(CUSTOM_PREFIX) }?.let { CustomSound(it.removePrefix(CUSTOM_PREFIX)) }
}
